# RDstat web app: t-test, ANOVA (CRD / RCBD / split plot / combined over sites), correlation and regression, following
# the methods of IRRI STAR. The analysis code in ./star (star_*.R) is generated by scripts/build_app.R from engine/R;
# it uses base R, agricolae, lmtest and mctest. The Classic STAR report runs STAR's own code from ./star/legacy.
library(shiny)

# Each analysis function is called only a few times per analysis, so JIT compiling it on first use costs more than it
# saves.
compiler::enableJIT(0)
# Packages used by the code in ./star; this line (never run) lets Shinylive see that they must be bundled
if (FALSE) {
  readxl::read_excel
  agricolae::LSD.test
  nortest::lillie.test
  lmtest::bptest
  mctest::imcdiag
  ragg::agg_png  # PNG plots drawn in R; webR's own png() draws on the browser canvas, which Brave blocks
}
for (f in sort(list.files("star", pattern = "[.]R$", full.names = TRUE))) {
  source(f, local = FALSE)
}
# STAR's own functions, used only by star_report() for the Classic STAR report. They are kept in an environment of
# their own so that STAR's LSD.test(), cv(), data.frame() shim and the like do not mask the ones the analyses use.
# It is made in the global environment, where star_report() looks for it: shiny::runApp() runs this file in a child
# environment of it.
star_legacy <- assign(
  "star_legacy",
  new.env(parent = globalenv()),
  envir = globalenv()
)
for (f in sort(list.files(
  file.path("star", "legacy"),
  pattern = "[.]R$",
  full.names = TRUE
))) {
  sys.source(f, envir = star_legacy)
}
# UseMethod() finds methods in the caller's environment or in the S3 table of the top environment of the generic.
# A .packageName makes star_legacy a top environment (see ?topenv); its table holds the methods of STAR's generics
# (AOVTest.default, cv.data.frame, ...), as a package namespace would.
assign(".packageName", "STARlegacy", envir = star_legacy)
local({
  tbl <- new.env(hash = TRUE, parent = baseenv())
  fns <- ls(star_legacy, all.names = TRUE)
  for (g in fns) {
    f <- star_legacy[[g]]
    if (is.function(f) && "UseMethod" %in% all.names(body(f))) {
      for (m in fns[startsWith(fns, paste0(g, "."))]) {
        tbl[[m]] <- star_legacy[[m]]
      }
    }
  }
  star_legacy[[".__S3MethodsTable__."]] <- tbl
})
# ggplot text uses Roboto (www/fonts, Apache 2.0). Registering the files with systemfonts lets ragg (on-screen plots
# and PNG export) find the font without it being installed; if registration fails, plots keep the device default font.
if (
  tryCatch(
    {
      if (!"Roboto" %in% systemfonts::registry_fonts()$family) {
        systemfonts::register_font(
          "Roboto",
          plain = "www/fonts/Roboto-Regular.ttf",
          bold = "www/fonts/Roboto-Bold.ttf"
        )
      }
      TRUE
    },
    error = function(e) FALSE
  )
) {
  options(star.plot_family = "Roboto")
}
# Roboto has no Thai letters: a plot with Thai text (titles, labels, treatment names) is drawn in Chulabhorn Likit
# instead, the app's own Thai font, which also has Latin letters and digits (see star_gg_font()).
if (
  tryCatch(
    {
      if (!"Chulabhorn Likit" %in% systemfonts::registry_fonts()$family) {
        systemfonts::register_font(
          "Chulabhorn Likit",
          plain = "www/fonts/ChulabhornLikitText-Regular.ttf",
          bold = "www/fonts/ChulabhornLikitText-Bold.ttf"
        )
      }
      TRUE
    },
    error = function(e) FALSE
  )
) {
  options(star.plot_family_thai = "Chulabhorn Likit")
}

# Code is split by role into ./src; each file is sourced in the same order as before, so definitions keep their dependencies.
source("src/helpers.R", local = TRUE) # formatting, display tables, data reading, UI building blocks
source("src/ui_components.R", local = TRUE) # data source / plot label / export controls
source("src/guide_boxes.R", local = TRUE) # "what you get" boxes under each choice
source("src/ui_screens.R", local = TRUE) # correlation, regression and t-test screens
source("src/tt_display.R", local = TRUE) # t-test result tables
source("src/designs.R", local = TRUE) # example datasets and design helpers
source("src/script_gen.R", local = TRUE) # R scripts that repeat an analysis outside the app

copy_js <- "
Shiny.addCustomMessageHandler('radio_support', function(msg) {
  var root = document.getElementById(msg.id); if (!root) return;
  var ok = [].concat(msg.ok);
  root.querySelectorAll('input[type=radio]').forEach(function(r) {
    var off = ok.indexOf(r.value) < 0, box = r.closest('.radio, .form-check') || r.parentElement;
    r.disabled = off; box.classList.toggle('opt-disabled', off); box.title = off ? msg.why : '';
  });
});
Shiny.addCustomMessageHandler('copy_text', function(msg) {
  var done = function(ok) { Shiny.setInputValue('copy_status', {ok: ok, what: msg.what, t: Date.now()}); };
  var fallback = function() {
    var ta = document.createElement('textarea'); ta.value = msg.text;
    ta.style.position = 'fixed'; ta.style.opacity = '0'; document.body.appendChild(ta); ta.select();
    var ok = false; try { ok = document.execCommand('copy'); } catch (e) {}
    document.body.removeChild(ta); done(ok);
  };
  if (navigator.clipboard && window.isSecureContext) {
    navigator.clipboard.writeText(msg.text).then(function() { done(true); }, fallback);
  } else { fallback(); }
});"

home_card <- function(id, icon_name, title, text, examples) {
  bslib::card(
    class = "home-card",
    bslib::card_body(
      div(class = "icon", icon(icon_name)),
      h4(title),
      p(text),
      p(class = "text-muted small mb-0", examples)
    ),
    bslib::card_footer(
      class = "bg-white border-0",
      actionButton(
        id,
        tagList("เริ่มวิเคราะห์ ", icon("arrow-right")),
        class = "btn-primary w-100"
      )
    )
  )
}
home_step <- function(n, title, text) {
  div(
    class = "step",
    div(class = "num", n),
    div(strong(title), br(), span(class = "text-muted small", text))
  )
}
